"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["8792"],{16409(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.opcao_declarada_fato.codigo_invalido","status":422,"titulo":"O c\xf3digo da op\xe7\xe3o \xe9 obrigat\xf3rio e respeita o tamanho m\xe1ximo"},"descricao":{"codigo":"uniplus.selecao.opcao_declarada_fato.codigo_invalido","requisitos":[],"oQueAconteceu":["O processo declara as op\xe7\xf5es de um fato cuja fonte dos valores \xe9 o pr\xf3prio\\nprocesso, como as edi\xe7\xf5es do ENEM aceitas. Cada op\xe7\xe3o tem um c\xf3digo, e o c\xf3digo\\nde pelo menos uma das op\xe7\xf5es enviadas n\xe3o pode ser usado: veio em branco, s\xf3\\ncom espa\xe7os, ou passou de 60 caracteres. Os espa\xe7os do in\xedcio e do fim n\xe3o\\ncontam.","A confer\xeancia percorre a lista inteira antes de recusar. A resposta traz um\\nerro por op\xe7\xe3o com problema, cada um indicando a posi\xe7\xe3o da op\xe7\xe3o na lista\\n(`opcoes[n].codigo`), e nada foi gravado, nem das op\xe7\xf5es que estavam corretas."],"comoResolver":["Informe, em cada op\xe7\xe3o apontada, um c\xf3digo preenchido com no m\xe1ximo 60\\ncaracteres, e envie a lista completa de novo. O pedido substitui todas as op\xe7\xf5es\\ndo fato, ent\xe3o a lista enviada precisa trazer tamb\xe9m as op\xe7\xf5es que j\xe1 valiam."],"ondeAparece":["Declara\xe7\xe3o das op\xe7\xf5es de um fato do processo seletivo (`PUT /api/selecao/processos-seletivos/{id}/fatos/{fatoCodigo}/opcoes`)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Opcao declarada fato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);